// Further independently written teaching for every remaining foundation lesson.
// Existing specialist sections/tables are retained. Old IDs stay available for backups and history.
const remainingGrammarLessons=[];
const remainingIntroGoals={sentence:'能找出主语、动词和直接对象，解释哪一项控制动词形式。',questions:'能按信息缺口选择疑问词，并正确安排no与其他否定词。',prepositions:'能区分位置、方向、来源、起点与固定搭配，不按中文单字硬套。',porpara:'能在明确场景中区分原因、目的、接收目标等关系，再选择por或para。',subjunctive:'先理解主句框架与主语关系，再选择原形或所需语气。',relative:'能恢复两个简单句，理解先行词、关系词、介词及cuyo一致。',passive:'能区分事件被动、结果状态、haber完成和两类se，再检查一致。',logic:'能辨认因果方向、转折与让步，选择相应连接结构。'};
function continueGrammar(p){
 const id='foundation-'+p.id,f=foundationLessons.find(f=>f.id===id);if(!f||f.genderLesson)throw Error('Unexpected remaining lesson '+id);
 const previous=f.deep,original=f.questions.map(q=>({...q}));
 const rules=previous?.sections||[[p.ruleTitle||'把规则逐条看清楚',f.paragraphs]];
 const sections=[rwSection('meaning','先把术语和表达目的弄懂',p.teaching,['本节概念或词','怎样理解','具体例子'],p.terms),
 ...rules.map(([title,paragraphs],i)=>rwSection('rule-'+i,title,paragraphs)),
 ...(f.precisionDetails||[]).map((d,i)=>rwSection('detail-'+i,d.title,d.paragraphs,d.columns,d.rows)),
 rwSection('errors','把容易混淆的两种分析分开',[p.trap[2],...p.examples.map(e=>e.zh+'：'+e.steps.join(' '))],['容易误判','应怎样理解'],[[p.trap[0],p.trap[1]]])];
 const groups=[rwGroup('starting','meaning','先只练新讲清的这个小问题','题目提供词义与条件；先辨认规则，再独立填写。',...p.questions)];
 const seen=new Set();original.forEach((q,i)=>{const fingerprint=q.prompt+'|'+q.answer;if(seen.has(fingerprint))return;seen.add(fingerprint);const n=p.targets?.[i]??Math.min(i,rules.length-1),section='rule-'+Math.min(n,rules.length-1);let group=groups.find(g=>g.section===section);if(!group){group=rwGroup('applied-'+section,section,'专练：'+rules[Math.min(n,rules.length-1)][0],'先读本条规则，再做对应应用；题目解析同时给出检查顺序。');groups.push(group)}delete q.supersededBy;q.explain=q.explain+' 检查顺序：'+p.checks.join(' → ')+'。';group.questions.push(q)});
 // More than a short rule: new terminology, explicit interpretation, worked steps, old specialist rules and targeted practice.
 const examples=[...p.examples,rwExample(p.trap[1],'易错辨析',p.trap[0],p.trap[2],p.checks.join(' → ')),...(previous?.examples||f.anatomy).filter(e=>!p.examples.some(x=>x.word===e[0])).map(([word,zh,why])=>rwExample(word,zh,why))];
 installGenderLesson(p.id,p.title||f.title,previous?.goal||remainingIntroGoals[p.id]||p.teaching[0],sections,examples,groups,examples,p.trap,p.related||[],{registry:remainingGrammarLessons,prefix:'continued',source:'在原有专项细则上独立补写中文术语解释、分步分析与新练习，参照用户教材的分项讲解方式；保留原有专门规则和表格。不表示已逐页验收两书全部内容。',intro:'本专题可独立查阅，不需要先读文章。先看词义和术语，再跟着具体例子走判断过程；每条规则后有对应练习。',relatedNote:'可按需要查其他专题；不强制按课程顺序阅读。'});
 const l=remainingGrammarLessons.at(-1);l.revision='remaining-2026-10-25';l.newStarterQuestions=p.questions.length;l.preservedRuleSections=rules.length;
}
continueGrammar({id:'sentence',title:'句子入门：先分清谁做、做什么、涉及谁或什么',teaching:[
 '先看Ana compra un libro（Ana买一本书）。Ana是做“买”这个动作的人，叫主语；compra表示买，是动词；un libro是买的东西，在这个句子中叫直接宾语。三个名称描述的是句中角色，不是给每个生词永远贴同一个标签。',
 '中文“书很多”不能决定“买”的形式。Ana compra libros里做动作的仍是Ana一个人，所以compra不因libros复数就变compran。只有把主语改成Ana y Luis（两个人），才改用compran。',
 '西语常能省略可从语境和动词认出的主语：Compro un libro就是我买一本书。省略的是yo（我），不是动词。先圈出动作，再找谁承担动作；不要机械把句子第一个词判成主语。'],terms:[['主语','本句在说谁或什么','Ana compra：Ana做买的动作'],['动词','表达动作、状态等','compra：买'],['直接宾语','本例中买的东西','un libro：一本书']],examples:[rwExample('Ana compra dos libros.','Ana买两本书。','先找动作compra。','做动作的是Ana，不是libros。','按Ana第三人称单数选compra。'),rwExample('Compro un libro.','我买一本书。','compro的形式提示我。','语境清楚时不写yo也可。','保留compro，不改回原形comprar。')],trap:['看见libros复数就把compra改compran','先找主语Ana，再选compra','宾语的数量和主语的数量不是同一个问题；把角色先分开，才能检查动词。'],checks:['找句中动作','找动作由谁承担','按主语选动词'],questions:[rwInput('Ana compra un libro（Ana买一本书）。只填主语的人名。','Ana','买的动作由Ana承担。'),rwChoice('Ana compra libros中，libros表示什么？','买的东西',['买的东西','买东西的人','动词'],'本例libros是直接宾语，不控制compra的人称。'),rwInput('Ana y Luis ___ libros（买书）. 使用已给对应compra/单数、compran/复数。','compran','两个人作主语，选第三人称复数compran。')],targets:[0,0,0],related:['foundation-bridge-people','foundation-verb','foundation-topic-transitivity']});
continueGrammar({id:'sound',teaching:[
 '字母名称和词中的声音要分开：知道字母h的名字，并不表示hola（你好）里要读出一个h音。西语五个元音a、e、i、o、u通常要清晰发出；ñ是不同于n的字母，不是随意加的装饰。地区读音有差异，不把某一个地区当唯一标准。',
 '音节可以理解为说词时一次次发声的单位；重读是其中较突出的那一节，重音符号是á、é、í、ó、ú上的书写记号。casa重读ca而不写符号；café重读fé并需要é。不能把“读得重”一律理解成“都要标符号”。',
 '先听和读词，再学通常的重读判断：常见元音、n或s结尾词默认倒数第二音节重读，其他常见辅音结尾默认最后一节；辅音群等有额外边界。hablo（我说）和habló（他说了）也提醒你，符号可改变形式和意义。下面再分别处理拼读、大小写和成对标点。'],terms:[['音节','词中的发声单位','ca-sa有两节'],['重读','某一音节更突出','café重读fé'],['重音符号','写在元音上的符号','habló的ó']],examples:[rwExample('casa / café','房子 / 咖啡','分别读ca-sa、ca-fé。','casa的重读符合常见默认规则。','café需用é明确最后一节重读。'),rwExample('¿Dónde vives?','你住哪里？','这是直接问住处的句子。','开头¿、结尾?标出问题范围。','疑问词dónde也保留ó，不只添问号。')],trap:['每个重读元音都写重音符号','先看通常读法能否表达实际重读','重读和重音符号不是一回事；另外，tú/tu等区别性重音要结合语法功能学习。'],checks:['听实际读音','划音节找重读','核对符号与功能'],questions:[rwChoice('casa（房子）重读ca，但不写á，这说明什么？','重读不一定需要书面重音符号',['重读不一定需要书面重音符号','casa没有重读','所有a都不能标重音'],'符合默认重读规则时通常不用额外符号。'),rwInput('把本题已教的“咖啡”cafe写出正确重音形式。','café','本词最后一音节重读，写é。'),rwChoice('hola里的h在本节所说的常见读法中怎样？','不发音',['不发音','像英语hello的h','必须长颤音'],'字母名字与词中发音不同。')],targets:[2,2,0,3,3,4],related:['foundation-topic-spelling-sounds','foundation-bridge-plural']});
continueGrammar({id:'verb',teaching:[
 '原形是词典入口，如hablar（说话）；变位是它在特定语气、时间、人称和数下的形式，如hablo（我说）、hablas（你说）。今天先固定为直陈式现在时，再观察谁做动作，避免把几十种形式一次混在一起。',
 '词干是去掉原形末尾-ar、-er或-ir后剩的部分。hablar→habl-，comer（吃）→com-，vivir（居住）→viv-。本课规则动词把对应词尾接到词干，不接到整个原形上；不规则词要另外核对。',
 '一个句子不保证只有一个动词需要变位，也不是所有动词都照同一人称改。Puedo hablar（我能说）中puedo已经配我，hablar受poder框架要求用原形；Creo que Ana trabaja（我认为Ana工作）中两小句各有自己的主语和变位。先识别结构，再决定哪一处用什么形式。'],terms:[['原形','词典中列出的形式','hablar'],['词干','本例去-ar后剩的部分','habl-'],['变位形式','进入特定人称和时态的形式','hablo']],examples:[rwExample('yo + hablar → hablo','我说话','先固定现在时和规则动词。','去-ar，保留habl-。','我组接-o，得到hablo。'),rwExample('Puedo hablar español.','我能说西语。','本例poder表达能。','puedo已对应我。','后接hablar原形，不再写hablo。')],trap:['一句话有两个动词就都按同一个主语变位','先看各小句和动词搭配','Puedo hablar与Creo que Ana trabaja结构不同；不要把前一种的原形规则扩大到所有两个动词的句子。'],checks:['固定时态与结构','找各动词的主语或搭配要求','选变位或原形'],questions:[rwInput('hablar（说话）去掉末尾-ar，只写词干，不加连字符。','habl','去掉最后两个字母，剩habl。'),rwChoice('hablo在本节是什么？','hablar的一种变位形式',['hablar的一种变位形式','所有动词的原形','一个人称代词'],'hablo是hablar的直陈式现在时我组。'),rwInput('我能说：Puedo ___. 使用hablar的适当形式。','hablar','poder后在本框架中接原形。')],targets:[3,5,3,2,1,1,4,5],related:['foundation-bridge-present-ar','foundation-bridge-present-er-ir','foundation-topic-object-clauses']});
continueGrammar({id:'questions',teaching:[
 '疑问句先看要补哪一种信息。想知道“在哪里”用dónde；问“谁”用quién；问“什么”用qué。¿Dónde vives?（你住哪里）中的dónde问地点，不是让你先回答是否。问句不需要照搬英语的do。',
 '否定一个通常陈述，常把no放在变位动词前：Vivo aquí（我住这里）→No vivo aquí（我不住这里）。如果有前置宾语代词，常见顺序是No lo sé（我不知道这件事），而不是把no插在代词与动词之间。',
 'nadie表示没人，nada表示没有什么。它们在动词后时通常需要前面的no：No vino nadie（没人来）；在动词前时一般不再加no：Nadie vino。这里不是数学中的负负得正，而是西语的否定呼应。下面先分问句与否定，再作对应练习。'],terms:[['dónde','询问地点','¿Dónde vives?'],['no','常置于变位动词前否定','No vivo aquí.'],['nadie','没有人','No vino nadie.']],examples:[rwExample('¿Dónde vives?','你住哪里？','所缺信息是住处。','选带重音的疑问词dónde。','保留你组动词vives，配成对问号。'),rwExample('Nadie vino. / No vino nadie.','没人来。','两句都在否定人的出现。','nadie在前，通常不另加no。','nadie在后，通常与no呼应。')],trap:['看见no和nadie就当成肯定','按西语否定词位置理解','不把中文或数学规则硬套进西语；本例两种位置都表达没人来。'],checks:['确定信息缺口或否定范围','看否定词前后位置','核对动词与标点'],questions:[rwInput('补“哪里”：¿___ vives? 保留疑问词重音。','dónde','问地点用dónde，ó参与规范拼写。'),rwInput('我不住这里：___ vivo aquí. 只填否定词。','no','本例no放在变位动词前。'),rwChoice('No vino nadie的意思是什么？','没有人来',['没有人来','每个人都来了','不知道谁来了'],'后置nadie与前置no构成否定呼应。')],targets:[0,0,0],related:['foundation-topic-question-order','foundation-topic-exclamations']});
continueGrammar({id:'gustar',teaching:[
 '先把gustar想成“某物让某人喜欢”这个分析框架。Me gusta este libro（我喜欢这本书）中，este libro是被喜欢的东西，也是控制gusta的主语；me指出体验喜欢的人。不要因为中文开头说“我”，就改成gusto来表示同一件事。',
 '换喜欢的人：Me gusta este libro→Nos gusta este libro（我们喜欢这本书），改变me/nos，书仍单数，gusta不变。换喜欢的东西：Me gustan estos libros（我喜欢这些书），这次libros复数，才把动词改gustan。每次只换一处，看清谁控制哪种形式。',
 'gustar后若谈活动，Me gusta leer（我喜欢阅读）把leer这个活动作为整体，常用单数gusta。A Ana le gusta leer（Ana喜欢阅读）中a Ana明确体验者，le保留；而“饿了”常用Tengo hambre，不是给所有感受都套gustar。'],terms:[['体验者','谁产生喜欢、疼痛等感受','me：本例是我'],['主语','本结构中被喜欢的东西或活动','este libro / leer'],['gusta / gustan','随相关主语的数变化','libro单数；libros复数']],examples:[rwExample('Nos gusta este libro.','我们喜欢这本书。','体验者我们取nos。','被喜欢对象este libro为单数主语。','因此用gusta，不因我们多人改gustan。'),rwExample('Me gustan estos libros.','我喜欢这些书。','体验者我取me。','主语estos libros为复数。','动词相应取gustan。')],trap:['me表示我，所以gustar必须变成gusto','先区分体验者me与句子主语','中文译法的句首不直接等于西语主语；先找被喜欢的对象，再决定gusta或gustan。'],checks:['找体验者','找被喜欢的对象或活动','按该主语选动词'],questions:[rwInput('我喜欢这本书：Me ___ este libro. 用gustar现在时。','gusta','este libro是单数主语，me是体验者。'),rwInput('我们喜欢这本书：___ gusta este libro. 只填体验者代词。','nos','体验者由我变我们，me→nos；单数书仍配gusta。'),rwInput('我喜欢这些书：Me ___ estos libros. 用gustar现在时。','gustan','libros是复数主语。')],targets:[3,4,4,1,2,3,3,4],related:['foundation-topic-transitivity','foundation-bridge-indirect','foundation-topic-core-verbs']});
continueGrammar({id:'pronouns',teaching:[
 '先看Doy un libro a Ana（我给Ana一本书）。给的东西un libro是直接宾语，接收者a Ana是间接宾语。代词是把已知对象换成短形式，不是只记中文“他/她”，还要保留在句中承担什么角色。',
 '先只换书：Lo doy a Ana；先只换接收者：Le doy un libro。两个一起换时，间接宾语放前，直接宾语放后，le/les在lo/la/los/las前变se，所以Se lo doy。se在这里不表示自己，也不能单凭se分出给一个人还是多人。',
 '普通变位动词前置：Se lo doy；肯定命令后接：Dáselo（把它给她/他/您），并检查重音；否定命令前置：No se lo des。需要先会动词形式再检查位置，不能把“给她”理解为每次都只用同一串不变的词。'],terms:[['直接宾语','本例中给的物品','un libro→lo'],['间接宾语','本例中接收者','a Ana→le'],['le/les→se','紧接lo/la/los/las前的组合变化','le+lo→se lo']],examples:[rwExample('Se las doy.','我把那些钥匙给她/他等。','las llaves（钥匙，f.复数）换las。','一个接收者用le，多个用les。','在las前两者都变se，得到Se las doy。'),rwExample('No se lo des.','别把它给她/他等。（tú）','否定tú命令使用des。','代词放在变位动词前。','先间接se后直接lo，不写le lo。')],trap:['se lo中的se一定表示自己','本例se可能由le或les组合变化而来','同一个se有多种结构功能；送物语境中先恢复给的东西和接收者，再判断。'],checks:['恢复完整对象','分直接与间接角色','检查组合、位置与重音'],questions:[rwChoice('Doy un libro a Ana中，接收者是谁？','Ana',['Ana','un libro','yo'],'a Ana是本例接收者，书是物品。'),rwInput('Le doy el libro. 同时替换el libro：___ lo doy.','se','le在直接宾语代词lo前变se。'),rwInput('给她/他们那些钥匙：Se ___ doy. 已知钥匙las llaves为f.复数。','las','直接对象钥匙决定las，接收者人数不决定las。')],targets:[2,3,1,2,1,3,2,3],related:['foundation-bridge-direct','foundation-bridge-indirect','foundation-topic-commands']});
continueGrammar({id:'past',teaching:[
 '过去时不只是按事情距离今天远近排队。先决定怎样讲：Estudié（我学习了）可把经历作为有边界整体；Estudiaba（我当时在学习/以前常学习）可以展开背景或习惯。所谓未完成并不保证动作后来没有完成。',
 '同一画面可以有两种视角：Estudiaba cuando sonó el teléfono（我在学习时电话响了），estudiaba铺开学习背景，sonó把电话响起作为进入画面的事件。不是因为两件事都发生在昨天就必须用同一个时态。',
 '复合时态再引入参照点：He comido（我吃过/吃完了）的具体使用有地区差异；Ya había comido cuando llegué此类先后关系要看各主语，明确谁在谁之前吃过。本课例句Cuando llegué, Ana ya había comido说我到时Ana已吃完：había comido早于llegué。'],terms:[['整体叙述','把一段经历当有边界整体讲','Estudié diez años.'],['展开背景','从过去事件内部看','Estudiaba cuando sonó…'],['过去的过去','早于另一个过去参照','Ana ya había comido.']],examples:[rwExample('Viví allí diez años.','我在那里住了十年。','题目指定把十年视为已结束阶段。','不是看到时间长就自动选未完成时。','以整体经历说，用viví。'),rwExample('Cuando llegué, Ana ya había comido.','我到时Ana已经吃完。','到达是过去参照点。','Ana吃完早于我的到达。','用había+分词comido组织先后。')],trap:['未完成过去时表示后来一定没完成','它主要表达叙述视角，不判定后来结局','先看背景、习惯、整体和先后关系；动作长短或“昨天”不足以决定句内每个时态。'],checks:['找时间参照','确定整体、背景或先后','再选主语对应形式'],questions:[rwChoice('把“住了十年”当已结束的整体阶段，可以用Viví吗？','可以',['可以','不可以，超过一天只能未完成时','不可以，viví不是动词'],'时长不排除简单过去整体视角。'),rwInput('我到时Ana已吃完：Cuando llegué, Ana ya ___ comido. 采用本节过去完成结构。','había','吃完早于过去到达，用había+comido。'),rwChoice('Estudiaba当学习背景，是否说明后来绝没学完？','不能据这个形式作此判断',['不能据这个形式作此判断','一定没学完','一定学完了'],'时态的内部视角与最终完成结果要分开。')],targets:[0,3,1,2,3,1,4,2],related:['foundation-topic-past-regular','foundation-topic-past-imperfect','foundation-topic-past-irregular']});
continueGrammar({id:'prepositions',teaching:[
 '介词是连接关系的小词，常放在名词、代词或其他成分前。Vivo en Madrid（我住马德里）里en引入居住位置；Voy a Madrid（我去马德里）里a引入目的地。中文都可能说“在/到”，西语要先看关系和动词框架。',
 'desde表示一个起点，hasta可表示终点：Vivo aquí desde 2020（我从2020年起住这里）。en 2020只是“在2020年”的时间点框架，不表达同样的持续起点。先找起点还是某时，不能因为都出现年份就选同一介词。',
 '有些介词由固定搭配要求，如darse cuenta de algo（意识到某事）。后面换成完整小句时仍保留de：Me di cuenta de que faltaba algo（我意识到缺了东西）。要连动词和补语框架学，不把每一个de都翻成中文“的”。'],terms:[['介词','连接成分、表达关系','en Madrid'],['起点','从哪里或何时开始','desde 2020'],['搭配要求','该结构要求的连接形式','darse cuenta de algo']],examples:[rwExample('Vivo aquí desde 2020.','我从2020年起住这里。','要表达持续的起点。','起点选desde。','不是只交代某一年的en 2020。'),rwExample('Me di cuenta de que faltaba algo.','我意识到缺了东西。','恢复darse cuenta de algo这个搭配。','把algo换为que引导的内容。','原结构要求的de仍保留。')],trap:['所有de都等于中文“的”','先看来源、所属、材料或搭配等关系','介词功能由结构和语境决定；不能按中文单字进行统一替换。'],checks:['找要连接的成分','识别关系或固定搭配','核对缩合与后接形式'],questions:[rwInput('我从2020年起住这里：Vivo aquí ___ 2020.','desde','本题明确持续起点，用desde。'),rwInput('在2020年这一时间状语：___ 2020.','en','只是交代某一年，使用en，不自动表达起点。'),rwInput('按darse cuenta de algo：Me di cuenta ___ que faltaba algo.','de','从名词内容换为que小句，不删除原搭配de。')],targets:[0,0,0],related:['foundation-topic-prepositions','foundation-porpara']});
continueGrammar({id:'porpara',teaching:[
 'por与para都可能在中文里译成“为”，但所表达关系不同。Este regalo es para Ana（礼物是给Ana的）突出预期接收者；Gracias por ayudarme（谢谢你帮助我）指出感谢的原因。先说清为什么/给谁/为了做什么，再选介词。',
 '目的常用para+原形：Estudio para aprender（我学习是为了学会）；原因常用por+名词或原形：por la lluvia（因为下雨）、por ayudarme（因为帮助我）。这只是两类常见框架，不是por后永不接动作、para后只接人物。',
 '表达路线可见Paseo por el parque（我在公园里散步），用途可问¿Para qué sirve?（它作什么用？）。别把路线、原因、接收者、目的和期限混进一个中文口诀。做题必须给出关系条件；孤立的Trabajo ___ Ana可能有不同分析。'],terms:[['原因','为什么发生或为何感谢','Gracias por ayudarme.'],['目的','为了达到什么目标','para aprender'],['预期接收者','给谁的','un regalo para Ana']],examples:[rwExample('Un regalo para Ana.','送给Ana的礼物。','题目说明礼物预期给Ana。','识别接收目标，而非交换或原因。','本例选para。'),rwExample('Gracias por ayudarme.','谢谢你帮助我。','感谢针对已经给出的帮助。','这是感谢的原因。','本例选por，后接ayudarme。')],trap:['中文有“为”就总用para','先分原因与目标等具体关系','同一中文词能对应多种西语关系；语境不充分时不制造唯一答案。'],checks:['说明具体关系','核对词或动词搭配','放回场景确认意思'],questions:[rwInput('指定“礼物预期给Ana”：un regalo ___ Ana.','para','本例明确预期接收者。'),rwInput('因为帮助我而感谢：Gracias ___ ayudarme.','por','感谢的原因用por。'),rwInput('学习的目的是学会：Estudio ___ aprender.','para','本题明确目的，使用para+原形。')],targets:[0,0,0],related:['foundation-prepositions','foundation-topic-prepositions']});
continueGrammar({id:'subjunctive',teaching:[
 '语气可以先理解为：说话者用什么方式呈现内容。直陈式常用来作报告或断言；虚拟式常出现在愿望、影响、评价等框架中。它不是“假话专用时态”，真实发生的事也可能成为情感评价的内容。',
 '先比较Creo que Ana viene（我认为Ana会来/来）与Quiero que Ana venga（我希望Ana来）。前句在表达认知断言，后句在表达对另一个人行动的愿望；这两个指定框架分别选viene和venga。不是所有que后面都用虚拟式。',
 '先分同主语还是不同主语：Quiero estudiar（我想学习）通常用原形，Quiero que estudies（我希望你学习）有两个主语，后面是完整从句。本节先把结构与用途认清，再去变位表学习具体形式，不要求凭空猜出所有不规则词。'],terms:[['语气','内容如何被呈现','报告、愿望或评价等'],['从句','句内有自己结构的小句','que Ana venga'],['虚拟式','本节愿望框架所需形式','venir→venga（第三人称单数）']],examples:[rwExample('Quiero estudiar.','我想学习。','希望的人和学习的人都是我。','本课愿望框架采用同主语原形。','直接接estudiar，不造que estudio。'),rwExample('Quiero que Ana venga.','我希望Ana来。','主句希望者是我。','从句来的人是Ana。','本例意愿框架用给定虚拟式venga。')],trap:['真实发生的事情绝不能用虚拟式','Me alegra que hayas venido可评价已发生事实','选择语气要看结构与内容呈现方式，而非只判断真实或不真实；本例是对你已经来的事情表示高兴。'],checks:['识别主句框架','比较各小句主语','选语气再查相应变位'],questions:[rwInput('我想学习：Quiero ___. 使用estudiar。','estudiar','同主语愿望通常接原形。'),rwInput('我希望Ana来：Quiero que Ana ___. 已给venir的此处虚拟式venga。','venga','本题不同主语的意愿框架取给定形式。'),rwChoice('看见que，就能保证后面一定是虚拟式吗？','不能，还要看结构和表达目的',['不能，还要看结构和表达目的','能，que本身决定所有语气','能，只看有没有重音'],'Creo que viene等报告框架说明不能只凭que判定。')],targets:[0,0,0],related:['foundation-topic-object-clauses','foundation-topic-conditions','foundation-topic-relative-time-place']});
continueGrammar({id:'relative',teaching:[
 '关系从句先从重复对象理解：Tengo un libro（我有一本书）与El libro es rojo（这本书是红色的），可以接成Tengo un libro que es rojo。que接住前面那本书，后面一小句补充说明它，不是另起一段毫不相关的话。',
 '被说明的前面对象叫先行词。la ciudad donde vivo（我住的城市）中ciudad是先行词，donde连接地点；与直接提问¿Dónde vives?的疑问词不同，本例关系donde通常不带重音。功能不同，书写也不同。',
 '从句原有搭配的介词常须保留：hablar con alguien（和某人交谈）→la profesora con la que hablé（我交谈过的那位女教师）。表示所属的cuyo则按后面的东西配性数：la autora cuyos libros leo，cuyos配libros，不配女作者autora。'],terms:[['先行词','前面被说明的对象','un libro'],['关系从句','补充说明该对象的小句','que es rojo'],['cuyos','本例按后面的名词配合','cuyos libros']],examples:[rwExample('Tengo un libro que es rojo.','我有一本红色的书。','两句重复的对象是libro。','用que连接说明这本书的小句。','es rojo仍描述这本书。'),rwExample('la profesora con la que hablé','我交谈过的那位女教师','恢复hablé con la profesora。','con来自hablar con alguien。','连接时保留con，不随意删除。')],trap:['cuyos要随女作者改成cuyas','本例cuyos配后面的libros','所有者与被拥有对象须分开：女作者可拥有阳性复数的书。'],checks:['找被说明对象','恢复从句原来结构','核对关系词、介词和一致'],questions:[rwInput('Tengo un libro. El libro es rojo. 合并：Tengo un libro ___ es rojo.','que','用que接回前面的libro。'),rwInput('按hablar con alguien：la profesora ___ la que hablé.','con','介词由从句原搭配保留。'),rwInput('女作者的书：la autora ___ libros leo. 用cuyo系列。','cuyos','后面libros为m.复数，选择cuyos。')],targets:[0,0,0],related:['foundation-topic-relative-time-place','foundation-topic-possessives']});
continueGrammar({id:'passive',teaching:[
 '主动句Los empleados enviaron las cartas（员工寄出了信）先说谁做动作；事件被动Las cartas fueron enviadas por los empleados先说受到动作的信。被动不是把中文“被”加进来就结束，还要选ser的时间形式和与主语配合的分词。',
 '信件las cartas为f.复数，所以事件被动用enviadas；haber完成结构Han enviado las cartas则用不随宾语配性数的enviado。Las cartas están abiertas（信处于打开状态）又是estar描述结果状态，不等于在叙述谁打开的动作。',
 '再区分两种se：Se venden libros（出售书）里libros作为被动主语，复数配venden；Se atiende a los clientes（接待顾客）中按非人称主线用单数atiende，不把人称a后的对象当被动主语。先恢复结构，再谈一致。'],terms:[['事件被动','把受动作对象放在主语位置','Las cartas fueron enviadas.'],['结果状态','描述现在处于什么状态','Las cartas están abiertas.'],['被动se','不说执行者的另一种结构','Se venden libros.']],examples:[rwExample('Las cartas fueron enviadas.','那些信被寄出了。','本句叙述寄送事件。','主语cartas为f.复数。','ser过去形式fueron，分词相应enviadas。'),rwExample('Han enviado las cartas.','他们寄出了那些信。','本句用haber复合时态。','enviado不按宾语cartas配阴性复数。','保持enviado，不写enviadas。')],trap:['所有分词都跟后面的名词变性数','先看haber完成、ser事件被动还是estar状态','不同结构的一致要求不同；不能因为都看到-ado/-ido就用同一套变化。'],checks:['确定叙述动作还是状态','判断主语与宾语角色','按对应结构检查一致'],questions:[rwInput('haber完成：Han ___ las cartas（信）. 用enviar的分词enviado。','enviado','haber完成中的分词不随宾语变为enviadas。'),rwInput('事件被动：Las cartas fueron ___. 已给enviado的阴性复数形式enviadas。','enviadas','分词与被动主语cartas配f.复数。'),rwInput('被动se：Se ___ libros. 用vender现在时单数vende或复数venden。','venden','本例主语libros复数。')],targets:[0,0,0],related:['foundation-topic-impersonal','foundation-topic-nonfinite']});
continueGrammar({id:'logic',teaching:[
 '连接词说明两条信息之间是什么关系。因为下雨所以不出门，是原因到结果；虽然下雨还是出门，是通常预期被突破。先把关系用中文说清，再选porque、por eso、pero或aunque，而不是挑看起来更高级的词。',
 'Llueve, por eso no salgo（下雨，所以我不出门）先说原因、后引结果；No salgo porque llueve（我不出门，因为下雨）先说结果、后引原因。两句因果方向相同，但连接词跟随组织方向改变。',
 'Aunque llueve, salgo（虽然下雨，我仍出门）表达让步。aunque后的语气要看是否作为事实断言、已知信息或假设等；不能因为出现aunque就让所有动词一律虚拟式。先学本节给定的事实表达，再查语气扩展。'],terms:[['原因','为什么出现结果','porque llueve'],['结果','由前述原因引出','por eso no salgo'],['让步','即使有阻碍仍成立','Aunque llueve, salgo.']],examples:[rwExample('Llueve, por eso no salgo.','下雨，所以我不出门。','第一件事下雨是原因。','第二件事不出门是结果。','引出结果用por eso。'),rwExample('No salgo porque llueve.','我不出门，因为下雨。','先说不出门这个结果。','后面补充下雨原因。','引出原因用porque。')],trap:['porque和por eso可以不看顺序随便换','先确定要引出的是原因还是结果','随便替换会改变因果关系或使结构不自然；句序与逻辑要同时看。'],checks:['分别概括两条信息','确定因果、转折或让步','选择连接结构并核对语气'],questions:[rwInput('下雨，所以不出门：Llueve, ___ no salgo. 填本节两个词的结果连接语。','por eso','前因后果，用por eso引出结果。'),rwInput('不出门，因为下雨：No salgo ___ llueve.','porque','后面解释原因，用porque。'),rwChoice('“虽然下雨仍出门”体现哪种关系？','让步',['让步','下雨是出门的结果','完全没有逻辑关系'],'本例表达阻碍存在但结果仍成立。')],targets:[0,0,0],related:['foundation-subjunctive','foundation-topic-conditions']});
continueGrammar({id:'bridge-people',teaching:[
 '人称说明从谁的角度指人：说话的我用yo，对面熟悉的你用tú，谈到的他/她用él/ella。usted也是对听者说“您”，但在变位表中与él/ella同组；交际称呼与动词语法组必须分开。',
 '多人时，我们用nosotros/nosotras，他们/她们用ellos/ellas。西班牙许多地区的非正式你们用vosotros/vosotras；拉美普遍用ustedes，也有vos等地区系统。本节分别列出，练习会明确指定人称，不把地区正常用法判错。',
 '人名和名词组也要先转换成对应组：Ana是第三人称单数，Ana y Lucía是第三人称复数。El hermano de Ana（Ana的兄弟）中心是一个hermano，不是两个人一起作主语。确定所指后，再选动词形式。'],terms:[['yo / tú','我 / 你','yo soy；tú eres'],['usted / ustedes','您 / 你们或诸位','usted es；ustedes son'],['主语中心','整个名词组主要指的对象','el hermano de Ana指那位兄弟']],examples:[rwExample('Usted es estudiante.','您是学生。','usted是礼貌称呼对方。','动词与él/ella同组。','ser现在时取es，不取tú的eres。'),rwExample('Ana y Lucía son estudiantes.','Ana和Lucía是学生。','两位被谈论的人。','可用ellas替换这个全女性组。','第三人称复数取son。')],trap:['中文“您”也是你，所以配tú变位','usted使用第三人称单数形式','先分交际称呼与语法组，之后所有动词都按所选组查表。'],checks:['确认指一个人还是一组人','映射到人称组','选相应变位'],questions:[rwInput('本题明确礼貌称呼“您”，填主语代词：___ es estudiante.','usted','usted配es。'),rwInput('Ana y Lucía是两位女性，用“她们”代词替换，只填代词。','ellas','全女性的第三人称复数。'),rwChoice('El hermano de Ana作主语，通常表示几位被定位的中心人物？','一位兄弟',['一位兄弟','Ana和兄弟两人同时作主语','三个同学'],'de Ana修饰hermano；中心指称为一个人。')],targets:[1,2,3,4,0,3],related:['foundation-sentence','foundation-verb']});
continueGrammar({id:'bridge-clock',teaching:[
 '先分两个问题：¿Qué hora es?问现在几点；¿A qué hora empieza la clase?问课程几点开始。报时常用Es la una或Son las dos，事件时间常用a la una或a las dos，不能因为中文都说“一点”就忽略结构。',
 '先记本节数字：una一点、dos二点、tres三点、nueve九点、diez十点、once十一点、doce十二点。正点后加y引分钟；cuarto是一刻，media是半点：las nueve y cuarto是九点十五，la una y media是一点半。',
 '用menos时，改以接下来那一小时为基准：一点五十分可说Es la una y cincuenta，也可说Son las dos menos diez。es/son跟当前说出的小时表达走，不能把实际钟表在1点这一小时就一概规定为es。下面再分别练报时和事件时间。'],terms:[['y','在小时后加分钟','y cuarto：加一刻'],['menos','距下一小时还差多少','las dos menos diez：1:50'],['a la / a las','说明事件在哪个钟点','a la una；a las dos']],examples:[rwExample('Son las once menos cuarto.','十点四十五。','用menos，以即将到的十一点为基准。','一刻cuarto即15分钟。','十一点减一刻，得到10:45。'),rwExample('La clase es a la una.','课在一点。','本题给事件时间，不是直接报现在几点。','使用a la una。','不要漏掉介词a。')],trap:['1:00—1:59任何表达都必须用es','用menos时要看实际说出的下一小时','1:50的Son las dos menos diez与Es la una y cincuenta都可；报时动词随所采用的小时表达。'],checks:['分报时或事件时间','确定y或menos的小时基准','检查es/son或a la/a las'],questions:[rwInput('九点十五：Son las nueve y ___. 填“一刻”。','cuarto','cuarto是一刻钟。'),rwInput('1:50指定用menos：Son las ___ menos diez. 填小时。','dos','以下一小时两点为基准，减十分钟。'),rwInput('课程在一点：La clase es ___ la una. 填介词。','a','事件时间用a la una，不只la una。')],targets:[0,1,2,2,3,3],related:['foundation-topic-calendar','foundation-topic-prepositions']});
continueGrammar({id:'bridge-reflexive',teaching:[
 '比较Ana lava a su hijo（Ana洗她的孩子）与Ana se lava（Ana洗自己）。后一句的se帮助说明动作与主语自身的关系。levantarse（起床）中的-se也提醒你这是带代词使用的词，词典原形不能直接放进所有人称。',
 '现在时先练两处配合：yo me levanto，tú te levantas，Ana se levanta，nosotros nos levantamos，vosotros os levantáis，ellos se levantan。代词说明相应人物关系，动词仍需要自己的变位，不是添一个se就不变动词了。',
 '普通变位动词前可放代词：Me levanto；本节ir a+原形结构中也可附在原形后：Voy a levantarme。不是所有带-se动词都能逐字译成“自己”，如quejarse（抱怨）等须按词条学习；先学当前起床与洗手，再看其他代词式用法。'],terms:[['代词式原形','词典中带-se的形式','levantarse：起床'],['me / te / se','本例随我、你、他等变化','me levanto；te levantas'],['身体部位结构','拥有关系明确时常用定冠词','Me lavo las manos：我洗手']],examples:[rwExample('Nos levantamos.','我们起床。','主语我们取nos。','levantarse按现在时我们组取levantamos。','代词与动词两处都检查。'),rwExample('Voy a levantarme.','我要起床。','ir a后本例接原形。','保留levantar这个原形主体。','我对应me附后，成为levantarme。')],trap:['看到-se就永远原样写se','先按人物选择代词，再检查动词','me levanto、te levantas、se levanta的变化来自同一人称关系；不能只改其中一处。'],checks:['确认代词式用法','选对应代词和动词人称','核对前置或后接位置'],questions:[rwInput('我起床：___ levanto. 只填代词。','me','yo对应me。'),rwInput('你起床：___ levantas. 只填代词。','te','tú对应te。'),rwInput('我们起床：Nos ___. 用levantarse规则现在时。','levantamos','nos配我们组，动词仍需-amos。')],targets:[1,3,1,1,2,4],related:['foundation-verb','foundation-topic-commands']});
continueGrammar({id:'bridge-direct',teaching:[
 '先找动作涉及的直接对象：Leo el libro（我读那本书）中el libro是读的东西；Veo a Laura（我看见Laura）中a Laura是看见的直接对象。对象是人时可能带a，不能看到a就一律判成间接宾语。',
 '本节第三人称直接宾语按常用lo/la主线：阳性单数lo、阴性单数la、阳性复数los、阴性复数las。代词跟被替换对象的性数，不跟说话者或买书的人性别；地区leísmo等另作扩展，不在基础题里当隐藏考点。',
 '普通变位动词前置：Leo el libro→Lo leo。否定时No lo leo；带原形的常见结构也可后接：Voy a leerlo（我要读它）。先只替换一个直接对象，熟悉后再去间接宾语与双代词专题。'],terms:[['lo / la','替换第三人称单数直接对象','el libro→lo；la revista→la'],['los / las','替换第三人称复数直接对象','los libros→los；las revistas→las'],['人称a','某些人物直接对象前的a','Veo a Laura']],examples:[rwExample('La leo.','我读它（那本杂志）。','恢复被替换对象la revista，f.单数。','选直接宾语代词la。','放变位动词leo前，写La leo。'),rwExample('Voy a leerlo.','我要读它（那本书）。','el libro为m.单数，选lo。','leer是原形。','本例lo可以附在原形后。')],trap:['凡有a的人物对象都是间接宾语','Veo a Laura中的Laura仍是直接宾语','角色取决于动词和结构；a不是万能的间接宾语标记。'],checks:['找被替换对象','按该对象性数选代词','检查动词形式和代词位置'],questions:[rwInput('Leo el libro. 书为m.单数：___ leo.','lo','el libro换lo；不用按说话者性别选。'),rwInput('Leo las revistas. 杂志为f.复数：___ leo.','las','las revistas换las。'),rwChoice('Veo a Laura中a Laura在本例是什么角色？','直接宾语',['直接宾语','只能是间接宾语','主语'],'看见的直接对象是Laura，人称a不改变这个角色。')],targets:[0,1,2,3,2,2],related:['foundation-topic-transitivity','foundation-bridge-indirect','foundation-pronouns']});
continueGrammar({id:'bridge-indirect',teaching:[
 'Doy un regalo a Ana（我给Ana一件礼物）中有两种对象：给什么→un regalo，给谁→a Ana。这里的接收者是间接宾语；先认清角色，再选代词，不要因为礼物是阳性就把接收者代词也按阳性选。',
 '第三人称间接宾语单数常用le，复数les：Le doy regalos给一个人很多礼物，Les doy un regalo给多人一件礼物。le/les分的是接收者的数，而lo/la/los/las分的是相应直接对象的性数。',
 '本节可见Le doy un regalo a Ana，代词le与完整接收者同现，并不等于错写两遍。两个对象同时代词化时，le/les在lo/la/los/las前变se：Se lo doy。此时se无法独自说明接收者几人，需要语境或补a Ana/a ellos。'],terms:[['间接宾语','本例的接收者','a Ana'],['le / les','第三人称接收者单数/复数','le给一人；les给多人'],['se lo','间接+直接代词组合','le/les在lo前变se']],examples:[rwExample('Le doy muchos regalos.','我给一个人很多礼物。','接收者只有一位。','选le，与礼物多少无关。','礼物的复数不把le变les。'),rwExample('Les doy un regalo.','我给多个人一件礼物。','接收者为多人。','选les。','即使礼物是一件，也不改成le。')],trap:['礼物很多，所以接收者代词一定是les','le/les要看给谁，不看礼物数量','把两个对象画成两列分别检查，避免把直接对象的数带给间接对象。'],checks:['分别找给什么和给谁','按接收者的数选le/les','组合时检查se与代词顺序'],questions:[rwInput('给Ana一人很多礼物：___ doy muchos regalos a Ana.','le','接收者单数Ana，选le。'),rwInput('给多位朋友一件礼物：___ doy un regalo a mis amigos.','les','接收者mis amigos复数，选les。'),rwInput('Le doy el libro双代词化：___ lo doy.','se','le在lo前变se，间接代词在前。')],targets:[0,1,1,3,3,4],related:['foundation-bridge-direct','foundation-pronouns']});
continueGrammar({id:'topic-demonstratives',teaching:[
 '指示词帮助定位“这个、那个”。先设一个明确场景：靠近我、靠近听者、远离双方，常分别用este、ese、aquel系列。距离是相对对话双方，不是死规定一米、两米；话语中还可指时间或刚谈过的事。',
 '先选距离系列，再按所指名词配性数：este libro（这本书，m.单数）、esta mesa（这张桌子，f.单数）、estos libros、estas mesas。说话者是男性还是女性不控制esta；mesa本身的性数才控制。',
 'esto/eso/aquello是中性形式，常指尚未命名的东西或整件事：¿Qué es esto?（这是什么？）。它们不直接放在名词前：这本书是este libro，不是esto libro。Este es mío可独立指回某本书，形式通常不因“代词”身份自动加区别重音。'],terms:[['este / esta','本节靠近说话者的一组','este libro / esta mesa'],['ese / aquel系列','按对话参照选择','esa mesa / aquella mesa'],['esto','未知事物或整件事的中性指代','¿Qué es esto?']],examples:[rwExample('Estas mesas.','这些桌子。','本题指定靠近说话者，选este系列。','mesas为f.复数。','取estas，不取estos或esto。'),rwExample('¿Qué es esto?','这是什么？','对象尚未命名。','使用独立中性esto询问。','不在esto后硬添libro。')],trap:['esto就是阳性单数“这个”，可放libro前','名词前是este libro，中性esto不这样限定名词','先分“给已知名词加指示词”和“指尚未命名的事物”两个任务。'],checks:['确定指代任务与距离参照','若限定名词则查性数','区分中性独立形式'],questions:[rwInput('靠近我，libro为m.单数：___ libro.','este','本题este系列阳性单数为este。'),rwInput('靠近我，mesas为f.复数：___ mesas.','estas','系列、性别、数逐步匹配。'),rwChoice('未知物品“这是什么”使用哪句？','¿Qué es esto?',['¿Qué es esto?','¿Qué es esto libro?','¿Qué es estas?'],'中性esto独立指尚未命名对象。')],targets:[0,3,1,1,2,4],related:['foundation-gender','foundation-bridge-plural','foundation-adjectives']});
continueGrammar({id:'topic-possessives',teaching:[
 '先分两个人物关系：谁拥有，拥有的是什么。mi libro（我的书）里mi说明拥有者是我；libro是被拥有的东西。sus libros可表示他、她、您或他们等的书，sus本身并不能告诉你拥有者有几个人。',
 'mi/mis、tu/tus、su/sus在名词前主要按被拥有名词的数变化，不因casa是阴性就把mi改成mia。nuestro系列还配被拥有对象的性：nuestra casa（我们的房子），即使拥有者全为男性，也选nuestra。',
 '名词后或本节表语结构要用重读形式：un amigo mío（我的一位男性朋友），La casa es mía（房子是我的）。mío/mía也配被拥有对象，不配说话者性别：女性说“我的男性朋友”仍是amigo mío。位置与形式要一起学。'],terms:[['拥有者','谁的','mi：我的'],['被拥有对象','拥有的东西或关系对象','libro / casa / amigo'],['重读物主形式','本节用于名词后或表语','mío / mía / míos / mías']],examples:[rwExample('Nuestra casa.','我们的房子。','拥有者是我们，选nuestro系列。','被拥有对象casa为f.单数。','所以取nuestra，不按拥有者性别选。'),rwExample('Un amigo mío.','我的一位男性朋友。','本结构物主词后置。','amigo为m.单数。','无论我本人性别，均取mío。')],trap:['女性说“我的”就一律写mía','mío/mía按被拥有对象配合','拥有者性别和被拥有对象语法性是两件事；先恢复名词再选形式。'],checks:['找拥有者','找被拥有对象及其性数','按前置、后置或表语选形式'],questions:[rwInput('拥有者都是男性：我们的房子，___ casa（f.单数）。用nuestro系列。','nuestra','形式配casa，不配男性拥有者。'),rwInput('我的几本书：___ libros. 用mi系列。','mis','libros复数，前置mi→mis。'),rwInput('我是一位女性，我的一位男性朋友：un amigo ___. 用mío系列。','mío','mío配amigo的m.单数，不配说话者。')],targets:[1,0,2,1,3,2,4,2],related:['foundation-adjectives','foundation-topic-demonstratives']});
continueGrammar({id:'topic-core-verbs',teaching:[
 'ir常说去哪里：Voy a Madrid（我去马德里）；ir a+原形也可说计划或即将做什么：Voy a estudiar（我要学习）。先看a后是地点名词还是动作原形，不把所有ir a都译成完全同一结构。',
 'tener常说有，也用于年龄和若干感受：Tengo veinte años（我二十岁）、Tengo hambre（我饿了）、Tengo sed（我渴了）。hambre、sed在这些结构中是名词，不能因为中文像“我很饿”就换成soy hambre。',
 'tener que+原形说明某主语承担义务：Tenemos que estudiar（我们必须学习）；hay que+原形表达不明确到某个语法主语的必要：Hay que estudiar（需要学习）。que是结构的一部分，后面的动作保留原形。下面再分别核对ir、tener的不规则形式。'],terms:[['ir a+地点','去某处','Voy a Madrid.'],['ir a+原形','计划或即将做某动作','Voy a estudiar.'],['tener que / hay que','指定主语义务 / 一般必要','Tenemos que estudiar.']],examples:[rwExample('Tengo veinte años.','我二十岁。','本节年龄用tener框架。','主语我对应现在时tengo。','后面veinte años，不用soy。'),rwExample('Tenemos que estudiar.','我们必须学习。','承担义务的人是我们。','tener配我们组tenemos。','保留que，后接原形estudiar。')],trap:['“我二十岁”按中文“是”直译成Soy veinte años','西语本节年龄使用tener años','应学习完整搭配，而不是把中文每个词强行对应到同一个西语词。'],checks:['辨地点、计划、年龄感受或义务','选指定动词框架','按主语变位并检查后接原形'],questions:[rwInput('我二十岁：___ veinte años. 用tener现在时。','tengo','年龄搭配tener años；yo→tengo。'),rwInput('我要学习：Voy a ___. 使用estudiar。','estudiar','a后表达要做的动作，本框架接原形。'),rwInput('我们必须学习：Tenemos ___ estudiar.','que','tener que+原形中的que不能删。')],targets:[2,3,0,1,1,3],related:['foundation-verb','foundation-gustar','foundation-topic-impersonal']});
continueGrammar({id:'topic-stem-patterns',teaching:[
 '不规则不等于毫无线索，也不等于可以把同一变化推到所有词。先固定直陈式现在时：pensar（想）在yo组为pienso，poder（能）为puedo，pedir（请求）为pido。前两类与第三类的元音变化不同。',
 '常见本节模式是重读词干中的e→ie、o→ue或e→i，而nosotros、vosotros在这些所列词现在时通常保留原词干：pensamos、podemos、pedimos。不要把pensar每一格都写成piens-，也不要因某个e词变化就让所有e词都变。',
 '同一词可能有多种特殊处：tener是tengo、tienes、tiene、tenemos、tenéis、tienen，yo的-go与其他组e→ie要分开记。所学分布也不能直接搬到过去时、虚拟式或命令式，需要分别核对。'],terms:[['词干变化','词尾前的部分发生变化','pensar→pienso'],['e→ie / o→ue','本节两类元音变化','pienso / puedo'],['e→i','不同于e→ie的一类','pedir→pido']],examples:[rwExample('yo pienso / nosotros pensamos','我想 / 我们想','先固定pensar现在时。','yo的重读词干用piens-。','nosotros在此用pens-，得到pensamos。'),rwExample('tengo / tienes','我有 / 你有','tener不是只用单一变化。','yo的特殊形式tengo单列。','tú用tienes，不能机械造tiengo。')],trap:['现在时某组变化就把所有人称和时态同样改','先限定词、时态和人称分布','规律帮助归类，但具体范式与变化范围必须一起记。'],checks:['固定原形和时态','找到人称对应变化格','保留正确词尾并核对特殊形式'],questions:[rwInput('pensar现在时，yo，使用本节给定形式：','pienso','本词yo组e→ie。'),rwInput('pensar现在时，nosotros：','pensamos','本词我们组保留pens-，不是piensamos。'),rwInput('pedir现在时，yo，本节给定e→i：','pido','本词取pid-加-o，不是piedo。')],targets:[1,3,1,2,0,4],related:['foundation-bridge-present-ar','foundation-bridge-present-er-ir','foundation-verb']});
continueGrammar({id:'topic-present-uses',teaching:[
 '“现在时”先是形式名称，不保证每句只描述说话这一秒。Trabajo los lunes（我每周一工作）说习惯；Estos días estudio mucho（这些天我学得很多）说当前阶段，都可以用同一现在时形式。',
 '要理解时间意义，读周围线索：todos los días（每天）、ahora（现在）、estos días（这些天）、mañana（明天）。Mañana salgo a las ocho在已有安排的语境下可以表示明天八点出发，不是出现mañana就把salgo认成错误。',
 '现在进行结构estoy estudiando（我正在学习）强调进行过程，但普通现在时也可按语境说当前动作，不能照英语-ing强制一一对应。题目如果没有给出是否习惯、安排或过程等条件，有时不止一种自然表达。'],terms:[['习惯','反复发生的安排','Trabajo los lunes.'],['当前阶段','覆盖最近一段时间','Estos días estudio mucho.'],['已安排未来','现在时结合未来时间语境','Mañana salgo a las ocho.']],examples:[rwExample('Trabajo los lunes.','我每周一工作。','los lunes给出习惯日程。','本句并不只说此刻这一秒。','可用现在时trabajo。'),rwExample('Mañana salgo a las ocho.','我明天八点出发。（已有安排）','mañana给未来时间。','题目明确已安排。','salgo现在时形式可承载该安排。')],trap:['现在时只能说此刻，所以mañana后不能出现','结合语境，现在时也可表达安排','形式与时间意义要分开辨认；不要用某个时间词替代对整句的理解。'],checks:['识别形式','读时间和场景线索','判断习惯、阶段、过程或安排'],questions:[rwChoice('todos los días表示哪种时间线索？','每天，常见习惯线索',['每天，常见习惯线索','仅昨天','永不发生'],'读到频率信息后再解释句子用途。'),rwChoice('已有明天出发安排，Mañana salgo a las ocho可否成立？','可以',['可以','不可以，mañana禁止现在时','必须删除mañana'],'本节明确安排语境允许现在时表达。'),rwInput('以现在时说习惯：Yo ___ los lunes. 用trabajar（工作）。','trabajo','本题主语我，规则现在时trabajo。')],targets:[0,3,1,3,2,1],related:['foundation-verb','foundation-topic-nonfinite','foundation-topic-calendar']});
continueGrammar({id:'topic-prepositions',teaching:[
 '先用同一地点比较：Vivo en Madrid（我住马德里）给位置，Voy a Madrid（我去马德里）给目的地，Soy de Madrid（我来自马德里）给来源。en、a、de不是三个都译成“在”就能任换的词。',
 'de也可连所属或材料：el libro de Ana（Ana的书）、una mesa de madera（木桌）。con常连陪同或工具：con Ana（和Ana）、con un lápiz（用铅笔）。介词后的人称形式也有自己的规则：para ti（给你）、conmigo（和我），不是para tú或con yo。',
 'a+定冠词el通常缩合al，de+定冠词el缩合del；a la、de los不这样缩合，代词él也不参与。交通常见en tren（乘火车），a pie（步行）；这些连具体表达记，不能把某条空间规则扩成所有固定搭配。'],terms:[['en / a / de','位置 / 目的地 / 来源等','en Madrid / a Madrid / de Madrid'],['conmigo / contigo','和我 / 和你','¿Vienes conmigo?'],['缩合','特定相邻形式合并','a+el→al；de+el→del']],examples:[rwExample('Voy al mercado.','我去那家市场。','本题目的地用a。','市场前给定定冠词el。','a+el缩合al。'),rwExample('El libro es para ti.','这本书是给你的。','para后面需要介词后形式。','你在本结构用ti。','不按主语代词写tú，也不给ti添重音。')],trap:['介词后照搬yo和tú','先核对介词后的人称形式','mí、ti、conmigo、contigo等与主语形式不全相同，必须连结构学。'],checks:['确定位置、方向等关系','核对搭配与后接形式','检查al/del缩合条件'],questions:[rwInput('住马德里：Vivo ___ Madrid.','en','本例en引入位置。'),rwInput('来自马德里：Soy ___ Madrid.','de','本例de引入来源。'),rwInput('和我：¿Vienes ___? 只填本节一个词的形式。','conmigo','con+我在此采用conmigo。')],targets:[0,1,2,4,3,5],related:['foundation-prepositions','foundation-porpara','foundation-bridge-articles']});
continueGrammar({id:'topic-commands',teaching:[
 '命令、请求和建议都可用命令式，实际礼貌程度还取决于语气、场景和称呼。先明确对谁说、肯定还是否定。本节规则tú肯定有habla、come、abre，不能因为都是“你”就拿普通现在时hablas来代替所有指令。',
 '否定tú不是简单在肯定前加no：habla（说吧）→no hables（别说），abre（打开）→no abras（别打开）。常用特殊肯定还包括di、haz、ve、pon、sal、sé、ten、ven；本节先给形式再练，不让初学者凭空猜。',
 '代词位置也随肯否变化：Dime（告诉我）肯定后接，No me digas（别告诉我）否定前置。Dáselo要重算重音；levantemos+nos→levantémonos还涉及词尾-s脱落。这些先在明确人称和已给词形下分项检查。'],terms:[['肯定tú','对熟悉的一个人作肯定指令','habla / come / abre'],['否定tú','让对方不要做某事','no hables / no abras'],['代词位置','肯定后接，否定前置的本节主线','dime / no me digas']],examples:[rwExample('No hables.','别说。（tú）','先定否定指令。','本节给hablar的对应形式hables。','no在前，不能写No habla表示相同tú指令。'),rwExample('Dime. / No me digas.','告诉我。/ 别告诉我。','肯定tú特殊形式di。','肯定代词me附后为dime。','否定用digas，代词me前置。')],trap:['把no加到肯定命令前就一定正确','先选对应否定形式，再安排代词','命令的肯否不只改变一个no，还可能改变动词形式和代词位置。'],checks:['确定人称与肯否','查相应命令形式','处理代词位置、脱落与重音'],questions:[rwInput('对tú：别说。No ___. 本节给定hablar否定形式hables。','hables','否定tú使用hables，不是habla。'),rwInput('肯定tú“告诉我”：di+me合成一个词。','dime','肯定命令代词后接。'),rwInput('否定tú“别告诉我”：No ___ digas. 填代词。','me','否定指令中me在变位动词前。')],targets:[3,4,1,3,5,4,2,5],related:['foundation-bridge-reflexive','foundation-pronouns','foundation-topic-stem-patterns']});
continueGrammar({id:'topic-question-order',teaching:[
 '提问先确定缺口：人→quién，地点→dónde，数量→cuánto系列。¿Quién vive aquí?（谁住这里）中疑问词自己就是主语；¿Dónde vive Ana?（Ana住哪里）中主语是Ana，dónde问地点，不能把两类句序机械套成完全一样。',
 'cuánto在名词前可随名词配性数：¿Cuántas clases tienes?（你有几节课？），clases为f.复数，所以cuántas。qué询问什么时本身不这样配性数。疑问词保留相应重音，不是只要前面加¿就可以省掉。',
 '介词来自所问成分的角色：hablar con alguien→¿Con quién hablas?（你和谁说话），ver a alguien→¿A quién ves?（你看见谁）。间接问句No sé dónde vive（我不知道住哪里）虽无外层问号，dónde仍有疑问功能和重音。'],terms:[['疑问缺口','需要补充的那类信息','dónde问地点'],['疑问主语','问题中承担主语角色的疑问词','¿Quién vive aquí?'],['间接疑问','把问题嵌入更大句子','No sé dónde vive.']],examples:[rwExample('¿Cuántas clases tienes?','你有几节课？','问的是课的数量。','clases是f.复数。','cuánto系列配成cuántas并保留á。'),rwExample('¿Con quién hablas?','你和谁说话？','恢复hablar con alguien。','提问对象仍需要介词con。','疑问词quién保留é。')],trap:['没有问号的句子里donde绝不能标重音','间接疑问dónde仍可带重音','按疑问功能判断，不只看句子外层有无问号；关系donde则要另分。'],checks:['确定缺哪种信息','找该成分的句中角色与介词','检查一致、词序和重音'],questions:[rwInput('问课的数量，clases为f.复数：¿___ clases tienes? 用cuánto系列。','cuántas','与clases配阴性复数，保留á。'),rwInput('我不知道住哪里：No sé ___ vive. 填间接疑问词。','dónde','间接疑问仍保留ó。'),rwInput('按hablar con alguien提问：¿___ quién hablas?','con','con来自原搭配，不可删除。')],targets:[0,1,3,4,2,2,2,2],related:['foundation-questions','foundation-relative','foundation-topic-transitivity']});
continueGrammar({id:'topic-object-clauses',teaching:[
 '宾语从句先理解成“把一整件事放在知道、相信、希望等动词后面”。Sé la respuesta（我知道答案）中答案是名词；Sé que Ana vive aquí（我知道Ana住这里）中que Ana vive aquí是一整块知道的内容，有自己的主语Ana和动词vive。',
 '主句和从句分别检查人称：Creo que mis amigos viven aquí中creo配我，viven配mis amigos（我的朋友们）。不能看到前面是我，就让后面朋友的动作也改成第一人称。',
 'que只是连接内容，不独自决定语气。Creo que Ana viene是认知表达；Quiero que Ana venga是意愿框架，采用本节给定的虚拟式venga。同主语愿望通常用Quiero estudiar。介词也依原搭配保留：acordarse de algo→Me acuerdo de que…'],terms:[['主句','外层知道、认为或希望等结构','Creo…'],['宾语从句','整块作为知道、认为等内容的小句','que Ana vive aquí'],['从句主语','从句内动作所对应的对象','mis amigos→viven']],examples:[rwExample('Creo que mis amigos viven aquí.','我认为我的朋友们住这里。','外层主语我，取creo。','从句主语mis amigos为复数。','从句用viven，不跟外层我改成vivo。'),rwExample('Me acuerdo de que era lunes.','我记得当时是周一。','恢复acordarse de algo。','内容换成que小句。','介词de仍由原搭配要求保留。')],trap:['一句话里所有动词都跟第一个主语变位','主句与每个从句分别找主语','从句有自己的结构；也要分别核对搭配介词与语气，不能只看que。'],checks:['分主句与内容小句','逐句找主语和搭配','按框架选语气与形式'],questions:[rwInput('Creo que Ana ___ aquí. 用vivir现在时；Ana为单数。','vive','从句动词配Ana，不配外层我。'),rwInput('Creo que mis amigos ___ aquí. 用vivir现在时。','viven','朋友们为第三人称复数。'),rwInput('按acordarse de algo：Me acuerdo ___ que era lunes.','de','内容小句不使原介词de消失。')],targets:[0,3,1,4,2,2,2,1],related:['foundation-subjunctive','foundation-sentence','foundation-prepositions']});
continueGrammar({id:'topic-conditions',teaching:[
 '条件句把条件和结果连接起来：Si tengo tiempo, iré（如果我有时间，我会去）。si引出的部分提出条件，iré给出对应结果。先分两件事，再选形式，不把整句所有动词按同一时态改。',
 '本节开放的未来条件主线是si+现在直陈式，结果可用将来、现在或指令：Si mañana tengo tiempo, iré。虽然条件说的是明天，常见开放条件中仍用tengo，不直接把条件部分写成将来tendré。',
 '更疏远假设有Si tuviera tiempo, iría（如果有时间，我就会去）；过去反事实有Si hubiera tenido tiempo, habría ido（如果当时有时间，我就去了）。这些先按整对结构理解，不能拆成两张随便拼的时态表。No sé si vendrá中的si则表示是否，不是这个条件连接任务。'],terms:[['条件','满足什么前提','si tengo tiempo'],['结果','前提成立时怎样','iré'],['si / sí','如果或是否 / 肯定回答是','Si tengo… / Sí.']],examples:[rwExample('Si mañana tengo tiempo, iré.','如果明天有时间，我会去。','本题给开放未来条件。','条件部分采用现在直陈式tengo。','结果用iré，不把两边强行同一时态。'),rwExample('No sé si vendrá.','我不知道他/她会不会来。','这里在表达不知道的内容。','si是是否，不是先决条件。','不能把条件句口诀照搬到此处。')],trap:['si后任何场合都不可能出现将来时','先分条件si和是否si','本课开放条件的主线不能扩大为所有名为si的结构；间接疑问有自己的规则。'],checks:['辨条件还是是否','确定开放、疏远或过去反事实','分别选条件与结果形式'],questions:[rwInput('开放未来条件：Si mañana ___ tiempo, iré. 用tener，我。','tengo','本节开放条件采用现在直陈式tengo。'),rwInput('写“如果”的连接词，不是肯定回答“是”。','si','条件si不写重音，sí是其他词。'),rwChoice('No sé si vendrá中的si表示什么？','是否',['是否','只要','肯定回答是'],'本例为间接是否疑问。')],targets:[1,2,1,0,4,2],related:['foundation-subjunctive','foundation-topic-object-clauses']});
continueGrammar({id:'topic-exclamations',teaching:[
 '感叹句表达惊讶、评价等，常配¡…!。¡Qué bonito!可说多漂亮，¡Qué bien!可说太好了；qué本身不按说话者性别变成另一形式。先看后面是形容词、副词还是名词。',
 '¡Qué bonitas son las flores!（花多漂亮）中bonitas描述flores（花，f.复数），不是因为说话者是女性。¡Qué día tan bonito!（多美好的一天）中día为m.单数，故bonito；-a结尾的día并不变成阴性。',
 'cuánto在名词前可配性数：¡Cuántas personas!（这么多人）。修饰动作则不同：¡Cuánto trabajas!（你工作真多）。还有¡Que tengas buen día!（祝你一天愉快）中的que是祝愿结构的连接词，不因有感叹号就一律写成qué。'],terms:[['qué感叹','本身不按性数变化','¡Qué bien!'],['形容词一致','描述对象决定形式','flores→bonitas'],['cuántas+名词','按本例名词性数配合','cuántas personas']],examples:[rwExample('¡Qué bonitas son las flores!','这些花多漂亮！','找被描述名词flores，f.复数。','bonito相应为bonitas。','qué本身不按花的复数改变。'),rwExample('¡Que tengas buen día!','祝你一天愉快！','这是本节指定祝愿结构。','que为连接词而非询问或程度感叹词。','因此此处que不加重音。')],trap:['只要有感叹号，所有que都标重音','按疑问感叹词与连接词的功能区分','标点不能替代语法分析；祝愿连接词que与¡Qué bien!中的qué不同。'],checks:['辨感叹或祝愿结构','找描述或数量对应的对象','核对性数、重音与标点'],questions:[rwInput('这些人这么多：¡___ personas! 用cuánto系列，personas为f.复数。','cuántas','数量词在本例名词前配阴性复数。'),rwInput('祝你一天愉快：¡___ tengas buen día! 只填连接词。','que','祝愿连接词que不加重音。'),rwChoice('一位女性说“太好了”，可以用¡Qué bien!吗？','可以',['可以','不可以，bien必须变阴性','不可以，qué必须变阴性'],'bien是副词，qué在此也不因说话者性别改变。')],targets:[1,1,3,3,2,2],related:['foundation-questions','foundation-adjectives','foundation-topic-question-order']});
continueGrammar({id:'topic-relative-time-place',teaching:[
 '先分连接对象、地点和时间三个任务。Tengo amigas que trabajan aquí（我有在这里工作的女性朋友）中que说明amigas；la ciudad donde vivo（我住的城市）中donde连接地点；Cuando tengo tiempo, leo（我有时间就阅读）中cuando给时间条件。',
 '关系词que自身通常不变，但后面动词仍配从句主语：la amiga que trabaja / las amigas que trabajan。不能因为que写法相同，就让单复数动词也永远相同。关系donde、cuando与带重音的疑问dónde、cuándo也须按功能分开。',
 '时间从句再看事件如何呈现：Cuando tengo tiempo, leo说一般习惯；Cuando tenga tiempo, te llamaré（等我有时间，我会给你打电话）指尚未发生的将来时间，用本节给定虚拟式tenga。不能只记“cuando后永远虚拟式”。'],terms:[['que','补充说明前面对象','amigas que trabajan'],['donde','本例连接地点','la ciudad donde vivo'],['cuando','连接时间关系','cuando tengo / cuando tenga']],examples:[rwExample('Las amigas que trabajan aquí.','在这里工作的那些女性朋友。','从句动作由amigas承担。','amigas为复数。','所以trabajan，不用trabaja。'),rwExample('Cuando tenga tiempo, te llamaré.','等我有时间，我会给你打电话。','题目指定尚未发生的未来时间。','本节时间从句采用给定形式tenga。','主句结果另取llamaré。')],trap:['看到cuando就不看语境一律虚拟式','习惯、已发生与尚未发生的呈现要分开','连接词不单独决定一切；要把时间参照与内容用途一起读。'],checks:['辨对象、地点或时间关系','恢复各从句主语','看事件呈现再选形式'],questions:[rwInput('我有在这里工作的女性朋友：Tengo amigas ___ trabajan aquí. 填连接词。','que','que接回前面的amigas。'),rwInput('习惯性“有时间就阅读”：Cuando ___ tiempo, leo. 用tener，我，现在直陈式。','tengo','题目明确一般习惯，不套未来时间虚拟式。'),rwInput('尚未发生未来：Cuando ___ tiempo, te llamaré. 本节已给tener对应形式tenga。','tenga','本题明确未来时间从句。')],targets:[0,2,1,3,3,2],related:['foundation-relative','foundation-subjunctive']});
continueGrammar({id:'topic-impersonal',teaching:[
 '没有写主语，不等于句子没有主语。Trabajo aquí（我在这里工作）能从trabajo恢复yo，属于省略主语。Hay libros（有书）和Llueve（下雨）的本节无人称用法，则不是随便补一个yo就能恢复同一种结构。',
 '存在义haber在规范主线中用单数式：现在hay，过去未完成había。Había muchas personas（当时有很多人）不因为personas复数就按本课规范主线改habían。助动词haber的复合时态形式又属于另一个系统。',
 'se也要分结构：Aquí se vive bien（这里生活得好）是非人称主线，用vive；Se venden libros（出售书）是被动se，libros作为复数主语，配venden；Se lo doy中se又可能是le/les的组合变化。不能一见se就译成自己或一概用单数。'],terms:[['省略主语','主语可从形式与语境恢复','Trabajo aquí.'],['无人称存在','本节规范主线不按后面的名词变复数','Había muchas personas.'],['非人称se / 被动se','须分别分析','se vive / se venden libros']],examples:[rwExample('Había muchas personas.','当时有很多人。','本句是存在义haber。','按本课规范主线用单数había。','后面personas不是据此改haber复数的主语。'),rwExample('Se venden libros.','出售书。','本句采用被动se分析。','libros是复数被动主语。','动词配venden，与se vive另分。')],trap:['所有带se句子都用单数','非人称与被动se须分别检查','同形se承担多种功能；先分析句子角色，再决定一致。'],checks:['辨省略主语或无人称','确定haber或se的具体用法','按对应结构检查数'],questions:[rwChoice('Trabajo aquí可恢复“我”，属于哪类？','省略可恢复的主语',['省略可恢复的主语','完全不存在主语','被动se'],'trabajo提示我，句中也没有se。'),rwInput('规范存在义：Ayer ___ muchas personas. 用haber未完成过去时。','había','存在义按规范单数主线用había。'),rwInput('被动se卖两栋房：Se ___ dos casas. 用vender现在时。','venden','本题被动主语dos casas复数。')],targets:[0,1,3,2,4,3],related:['foundation-core','foundation-passive','foundation-pronouns']});
continueGrammar({id:'topic-calendar',teaching:[
 '问日期是¿A qué fecha estamos?等日期框架，日常也常问¿Qué día es hoy?；问星期可用¿Qué día de la semana es hoy?。回答前先区分想知道几月几日，还是星期几，不把数字日期、星期、钟点混成一个任务。',
 '常见日期以日+de+月连接：el 12 de mayo（五月十二日），带年份可再接de 2026。月份名mayo、octubre和星期lunes通常小写，除非句首或其他特殊书写条件。每月一号有primero或uno等地区习惯，题目须给明确要求。',
 'el lunes可指某个星期一，los lunes在习惯日程中常表示每周一。Mi cumpleaños es el 12 de mayo说生日日期；Tengo veinte años说年龄，用的结构不同。另有Estamos a 12 de mayo、en 2026等框架，介词要随表达任务学。'],terms:[['de','连接日、月、年','el 12 de mayo de 2026'],['el lunes / los lunes','具体星期一 / 日程中的每周一','Tengo clase los lunes.'],['cumpleaños','生日；此处日期用ser','Mi cumpleaños es…']],examples:[rwExample('El 23 de octubre.','十月二十三日。','先写日23。','日与月用de连接。','月份octubre通常小写。'),rwExample('Tengo clase los lunes.','我每周一有课。','本题明确习惯日程。','星期名用复数冠词los。','lunes本身单复数同形。')],trap:['所有星期表达都只加el','看指定一天还是反复日程','el lunes与los lunes的选择牵涉时间组织，不只是背一个星期名称。'],checks:['确定日期、星期、生日或年龄任务','选完整时间框架','检查de、冠词与大小写'],questions:[rwInput('五月十二日：el 12 ___ mayo.','de','常见日期日与月用de连接。'),rwInput('指定习惯“每周一有课”：Tengo clase ___ lunes.','los','本题明确每周一的日程。'),rwInput('生日日期：Mi cumpleaños ___ el 12 de mayo. 用ser现在时。','es','生日日期采用本框架ser第三人称单数。')],targets:[1,3,4,1,0,3,3,3],related:['foundation-bridge-clock','foundation-topic-present-uses']});
continueGrammar({id:'topic-nonfinite',teaching:[
 '非人称形式先分三类：原形hablar（说话这个词典形式），副动词hablando（本课进行结构中的形式），分词hablado（本课完成结构等所用）。它们不按我、你、他本身变成六个人称格，但各自进入的句子框架不同。',
 '规则副动词常见-ar→-ando、-er/-ir→-iendo，另有leyendo、pidiendo等变化。Estoy leyendo（我正在阅读）中estoy配我，leyendo不因说话者性别改变；不是所有英语-ing都必须译成这个进行结构。',
 '规则分词常见-ar→-ado、-er/-ir→-ido；hecho、abierto、escrito等要单记。He abierto las ventanas是haber完成结构，abierto不随宾语变；Las ventanas están abiertas是状态，Las cartas fueron escritas是事件被动，后两者有相应一致要求。'],terms:[['原形','本节词典入口或框架要求形式','hablar'],['副动词','进行结构等所用形式','hablando / leyendo'],['分词','完成、状态或被动等结构所用','hablado / abierto']],examples:[rwExample('Estoy leyendo.','我正在阅读。','进行框架是estar+副动词。','estar配我取estoy。','leer副动词为leyendo，不按性别改词尾。'),rwExample('He abierto las ventanas.','我打开了窗户。','本句采用haber完成。','abrir分词是abierto。','不按宾语ventanas改成abiertas。')],trap:['所有分词遇见阴性复数名词都改-as','先辨haber完成、estar状态或ser被动','分词一致来自具体结构，不是只看附近名词的性数。'],checks:['确定原形、副动词或分词任务','核对规则与特殊形式','按所在结构检查一致'],questions:[rwInput('我正在阅读：Estoy ___. 使用leer的本节副动词leyendo。','leyendo','leer副动词本节为leyendo。'),rwInput('haber完成：He ___ las ventanas. 使用abrir分词。','abierto','特殊分词abierto在haber完成中不随宾语变。'),rwInput('状态：Las ventanas están ___. 已给abierto阴性复数形式abiertas。','abiertas','这里描述窗户状态，配f.复数ventanas。')],targets:[4,5,2,4,3,3,5,5],related:['foundation-past','foundation-passive','foundation-verb']});
continueGrammar({id:'topic-transitivity',teaching:[
 '及物、不及物先看当前动词用法怎样组织补语。Compro un libro（我买一本书）中书是直接宾语；Vivo en Lima（我住利马）里en Lima是位置补语。中文都可能紧接动词出现，西语角色却不同。',
 '人的直接对象有时带a：Veo a Ana（我看见Ana）；而Dependo de Ana（我依赖Ana）中的de来自depender de这个搭配，不把de Ana也当成同一类直接宾语。要还原动词框架，不用“介词后都是间接宾语”这类口诀。',
 '角色也不能只看中文句首：Me gusta la música（我喜欢音乐）中la música是主语，me是体验者。间接宾语也不一定总跟一个物品直接宾语同时出现，如Le hablo（我跟他/她说话）的本节分析。词典及物标签要结合当前义项和实际结构，不说明所有句子都显式写出宾语。'],terms:[['直接宾语','本例动作直接涉及的对象','Compro un libro.'],['介词要求的补语','动词搭配带特定介词','Dependo de Ana.'],['位置补语','说明动作或状态地点','Vivo en Lima.']],examples:[rwExample('Compro el libro → Lo compro.','我买那本书→我买它。','本句直接对象el libro为m.单数。','第三人称直接宾语取lo。','放变位动词compro前。'),rwExample('Dependo de Ana.','我依赖Ana。','恢复depender de alguien。','de由此动词用法要求。','不要只因人物出现就改成a Ana或直接lo。')],trap:['介词后面的人一律是间接宾语','先看人称a、动词配价介词和实际句中角色','Veo a Ana与Dependo de Ana结构不同；判断不能只看人或某一个介词。'],checks:['恢复该义项的动词框架','区分主语、直接/间接与介词补语','再用代词或一致检验'],questions:[rwChoice('Vivo en Lima中的en Lima表示什么？','位置补语',['位置补语','买的物品','本句主语'],'本例en引入住的位置。'),rwInput('本节depender de alguien：Dependo ___ Ana.','de','本义项依赖使用de。'),rwChoice('Me gusta la música中控制gusta的主语是什么？','la música',['la música','me','说话者性别'],'本结构音乐是被喜欢的主语。')],targets:[0,1,4,3,2,0],related:['foundation-sentence','foundation-bridge-direct','foundation-bridge-indirect','foundation-gustar']});
continueGrammar({id:'topic-past-regular',teaching:[
 '简单过去时先用于本节指定的整体叙述：Ayer hablé con Ana（昨天我和Ana交谈了）。不是动作短才准用，也不是只要昨天出现就让所有背景动词都同形；先理解视角，再学词尾。',
 '规则-ar去结尾后接-é、-aste、-ó、-amos、-asteis、-aron：hablé、hablaste、habló、hablamos、hablasteis、hablaron。规则-er与-ir在这个时态共用-í、-iste、-ió、-imos、-isteis、-ieron，如comí、comió、comimos。重音要连形式一起记。',
 'hablamos既可为现在时我们说，也可为简单过去我们说了，需读时间与场景。vivimos也有类似同形。不要因为形式同形就说西语没区别，也不要为了强行区分而自行添一个重音。下面的表和例句按六组完整核对。'],terms:[['简单过去整体','把本节事件当有边界整体讲','Ayer hablé…'],['-ar词尾','本节过去的对应形式','hablé / habló'],['-er/-ir同套尾','限于本节规则简单过去时','comimos / vivimos']],examples:[rwExample('yo + hablar → hablé','我说了。','先固定本节简单过去整体叙述。','去-ar取habl-。','我组加-é，写hablé。'),rwExample('nosotros + comer → comimos','我们吃了。','comer属于-er。','本时态与规则-ir共用我们组-imos。','写comimos，不搬现在时comemos。')],trap:['-er与-ir在所有时态都用同一词尾','本节共用指规则简单过去时','现在时我们组comemos与vivimos不同；规律必须注明适用时态。'],checks:['先确定整体过去视角','按原形类别去尾','加人称词尾并检查重音'],questions:[rwInput('hablar简单过去时，yo：','hablé','habl-加-é。'),rwInput('hablar简单过去时，ella：','habló','第三人称单数加-ó，不是现在时habla。'),rwInput('comer简单过去时，nosotros：','comimos','本节-er规则过去我们组-imos。')],targets:[2,3,1,2,0,4],related:['foundation-past','foundation-topic-past-imperfect','foundation-topic-past-irregular']});
continueGrammar({id:'topic-past-irregular',teaching:[
 '先限定简单过去时，再把不规则拆开：强词干tener→tuv-、estar→estuv-、poder→pud-等，配本组-e、-iste、-o、-imos、-isteis、-ieron。tuve、tuvo与规则hablé、habló的重音模式不同，不能看到过去就给结尾都添符号。',
 'j词干如decir→dij-、traer→traj-，第三人称复数为dijeron、trajeron，尾为-eron而非-ieron。ir与ser又共用fui/fuiste/fue/fuimos/fuisteis/fueron，需要句中补语判断是去了还是是，不靠词形单独猜。',
 '拼写和词干变化要另分：buscar的yo为busqué，为维持对应辅音拼写；dormir的第三人称单数为durmió，是本节-ir第三人称词干变化。并不是一个动词有一点变化，就让六个人称所有时态照同样算法改。'],terms:[['强词干','本组需单记的过去词干','tener→tuv-'],['j词干','本节复数尾注意-eron','dijeron'],['拼写调整','依后接元音维护相应拼写','buscar→busqué']],examples:[rwExample('ellos + decir → dijeron','他们说了。','先定decir简单过去。','本词取j词干dij-。','第三人称复数接-eron，写dijeron。'),rwExample('yo + buscar → busqué','我寻找了。','先定规则-ar过去我组-é。','c在此后接é时按本词改qu。','写busqué，保留é。')],trap:['dijieron只不过多写了一个可有可无的i','dijeron的-eron是本类实际词尾','词干、词尾、拼写和重音要分别核对，不能把规范差异当装饰。'],checks:['确定变化类别与人称','取该词实际词干和词尾','检查拼写及重音'],questions:[rwInput('tener简单过去时，yo，本节给定强词干tuv-：','tuve','tuv-加-e，写tuve，不加é。'),rwInput('decir简单过去时，ellos：','dijeron','dij-接-eron，不是dijieron。'),rwInput('buscar简单过去时，yo：','busqué','本词c→qu接é，写busqué。')],targets:[1,2,3,4,0,2],related:['foundation-topic-past-regular','foundation-topic-spelling-sounds']});
continueGrammar({id:'topic-past-imperfect',teaching:[
 '未完成过去时先用来从过去情境内部展开：Antes leía mucho（我以前常读很多）、Estudiaba cuando sonó el teléfono（电话响时我在学习）。语法名称“未完成”不等于现实中后来一定没完成；它讲述的视角与最终结果要分开。',
 '规则-ar接-aba、-abas、-aba、-ábamos、-abais、-aban；规则-er/-ir接-ía、-ías、-ía、-íamos、-íais、-ían。estudiábamos、leíamos等重音随实际形式记。yo与él/ella/usted在一些格同形，必要时补主语澄清。',
 '常用三个不规则另列：ser→era等，ir→iba等，ver→veía等；我们组分别éramos、íbamos、veíamos。习惯常与未完成视角相合，但有边界地数三次等也可用简单过去，不能用“长时间/多次”替代叙述分析。'],terms:[['内部背景视角','展开当时情境，不宣告后续结局','estudiaba'],['规则-ar','本节-aba系列','estudiábamos'],['规则-er/-ir','本节-ía系列','leíamos / vivíamos']],examples:[rwExample('Estudiábamos cuando sonó el teléfono.','我们学习时电话响了。','学习作展开的背景。','我们组未完成取estudiábamos。','电话响另作为事件用sonó。'),rwExample('éramos / íbamos / veíamos','我们当时是 / 我们以前去 / 我们当时看','分别识别ser、ir、ver。','查本时态我们组实际形式。','保留三个形式各自所需重音。')],trap:['未完成时只能用于最终没完成的动作','它提供过去背景等视角','后续是否完成需看语境；不要把时态中文名称当成事情结果判断。'],checks:['确定背景、习惯等叙事用途','辨原形类别或三个不规则','按主语检查词尾与重音'],questions:[rwInput('estudiar未完成过去时，nosotros：','estudiábamos','规则-ar我们组-ábamos。'),rwInput('vivir未完成过去时，tú：','vivías','-ir本节你组-ías，不能漏-s。'),rwInput('ser未完成过去时，nosotros：','éramos','本时态不规则我们组éramos。')],targets:[0,4,2,2,3,4],related:['foundation-past','foundation-topic-past-regular']});
continueGrammar({id:'topic-state-adjectives',teaching:[
 '先看本例究竟要说什么，再选ser或estar。Ana es lista常说Ana聪明；Ana está lista常说Ana准备好了。同一lista换框架不只改变持续时间，有时改变具体意思。题目必须把聪明或准备的语境给清楚。',
 'aburrido也要分谁和什么效果：La película es aburrida（电影无聊）描述电影的性质或给人效果；Ana está aburrida（Ana感到无聊）描述体验者状态。不要只看到中文“无聊”就固定选一个动词。',
 '选动词系统之后才检查一致：Las alumnas están listas（女学生们准备好了），alumnas复数让动词用están，f.复数让形容词用listas。bueno、verde也有多义，La fruta está verde在本节指定水果成熟语境可说未熟，不能把verde永远只译成绿色或未熟。'],terms:[['ser lista','本节常指聪明','Ana es lista.'],['estar lista','本节指准备好了','Ana está lista.'],['两种一致','动词看主语人称数；形容词看描述对象性数','Las alumnas están listas.']],examples:[rwExample('Ana está lista.','Ana准备好了。','题目明确准备状态。','采用本例estar lista搭配。','Ana单数，动词está，形容词lista。'),rwExample('La película es aburrida.','这部电影很无聊。','本句描述电影给人的无聊效果。','采用本例ser aburrida。','película为f.单数，形容词aburrida。')],trap:['同一形容词只要中文意思相近就随便换ser/estar','先读本例想表达的具体信息','有些换法带来不同意思；先确认搭配意义，再按各自对象检查词形。'],checks:['明确指定意思','选择该搭配的ser或estar','分别检查动词与形容词一致'],questions:[rwInput('明确表示Ana聪明：Ana ___ lista.','es','本节ser lista表达聪明。'),rwInput('明确表示Ana准备好了：Ana ___ lista.','está','本节estar lista表达准备状态。'),rwInput('明确女学生们已准备好：Las alumnas ___ listas. 用estar现在时。','están','复数主语配están，保留á。')],targets:[1,1,3,3,2,4],related:['foundation-core','foundation-adjectives']});
continueGrammar({id:'topic-spelling-sounds',teaching:[
 '先看字母后面的环境，不用一个汉字注音概括所有组合。c在ca/co/cu与ce/ci环境的规则不同；在que/qui中qu通常表示相应/k/，u不发音，如queso（奶酪）、quince（十五）。ce/ci的具体发音又有地区差异。',
 'g在ga/go/gu与ge/gi环境也要分开。guitarra（吉他）用gui保持相应的/g/，u通常不发音；pingüino（企鹅）中ü的双点提示这里的u要发音。双点不是普通书面重音，也不是提示把它读得更响。',
 'r/rr看位置：词首r如rojo常为多击，元音间r与rr可区别pero（但是）和perro（狗）。标准西语b/v通常不构成英语式两个对立音位；ñ则不同于n。ll/y等有地区差别，学习拼写时也不要误把正常地区声音都判错。'],terms:[['qu+e/i','本节u通常不发音','queso / quince'],['gu / gü+e/i','区分u不发音与要发音','guitarra / pingüino'],['r / rr','与位置一起判断','pero / perro']],examples:[rwExample('guitarra / pingüino','吉他 / 企鹅','先看后面i的字母环境。','guitarra的gui中u通常不发音。','pingüino的ü明确让u发音。'),rwExample('pero / perro','但是 / 狗','两个词都处在元音之间。','单r与rr在本例可构成区别。','拼写与听音都要分清，不把rr随便删掉。')],trap:['ü是普通重音，表示把u读重一点','本例ü提示u要发音','分音符与á等重音符号功能不同，必须分开识别。'],checks:['看前后字母和词内位置','确定该组合及地区读法','听音核对规范拼写'],questions:[rwChoice('queso中的u，本节常见读法怎样？','不发音',['不发音','一定重读','读成双r'],'qu在e前的该组合通常不发u。'),rwInput('企鹅：本节给pingüino，请写完整词并保留双点。','pingüino','ü提示本例u要发音。'),rwChoice('ü和é的主要作用是否相同？','不同，ü在本例标u发音，é是重音符号',['不同，ü在本例标u发音，é是重音符号','完全相同，都是加大音量','都表示不发音'],'功能不同，不能只当成相同装饰。')],targets:[1,2,2,2,4,3],related:['foundation-sound','foundation-topic-past-irregular']});
